{
  "analysis": "I found the critical bug: the LWL/LWR/SWL/SWR (unaligned load/store) implementations are incorrect. The masks and shifts are swapped, which corrupts data read from the WAD file, likely causing the 25MB allocation size. I need to fix all four instructions and re-test.",
  "plan": "Patch vm.js to fix LWL, LWR, SWL, and SWR with correct little-endian MIPS semantics. Then run syntax check and test the interpreter again.",
  "commands": [
    {
      "keystrokes": "python3 - <<'PY'
s = open('/app/vm.js').read()

# Fix LWL
old_lwl = '''    case 0x22: { // lwl
      const addr = R[rs] + simm;
      const al = addr & 3;
      const w = readU32(addr & ~3);
      const sh = al * 8;
      const mask = 0xffffffff >>> sh;
      setR(rt, ((R[rt] & ~(mask << 0)) | ((w << sh) & mask)) | 0);
      break;
    }'''
new_lwl = '''    case 0x22: { // lwl - little-endian: loads upper bytes of register
      const addr = R[rs] + simm;
      const al = addr & 3;
      const w = readU32(addr & ~3);
      const sh = al * 8;
      const mask = (0xffffffff << sh) >>> 0;
      setR(rt, ((R[rt] >>> 0) & (~mask >>> 0)) | ((w << sh) & mask));
      break;
    }'''
s = s.replace(old_lwl, new_lwl)

# Fix LWR
old_lwr = '''    case 0x26: { // lwr
      const addr = R[rs] + simm;
      const al = addr & 3;
      const w = readU32(addr & ~3);
      const sh = (3 - al) * 8;
      const mask = (0xffffffff << sh) >>> 0;
      setR(rt, ((R[rt] & ~mask) | ((w >>> sh) & mask)) | 0);
      break;
    }'''
new_lwr = '''    case 0x26: { // lwr - little-endian: loads lower bytes of register
      const addr = R[rs] + simm;
      const al = addr & 3;
      const w = readU32(addr & ~3);
      const sh = (3 - al) * 8;
      const mask = 0xffffffff >>> sh;
      setR(rt, ((R[rt] >>> 0) & (~mask >>> 0)) | ((w >>> sh) & mask));
      break;
    }'''
s = s.replace(old_lwr, new_lwr)

# Fix SWL
old_swl = '''    case 0x2a: { // swl
      const addr = R[rs] + simm;
      const al = addr & 3;
      const w = R[rt] >>> 0;
      const sh = al * 8;
      const mask = 0xffffffff >>> sh;
      writeU32(addr & ~3, ((readU32(addr & ~3) & ~mask) | ((w >>> sh) & mask)) >>> 0);
      break;
    }'''
new_swl = '''    case 0x2a: { // swl - little-endian: stores upper bytes of register
      const addr = R[rs] + simm;
      const al = addr & 3;
      const w = R[rt] >>> 0;
      const sh = al * 8;
      const mask = (0xffffffff << sh) >>> 0;
      writeU32(addr & ~3, ((readU32(addr & ~3) & (~mask >>> 0)) | (w & mask)) >>> 0);
      break;
    }'''
s = s.replace(old_swl, new_swl)

# Fix SWR
old_swr = '''    case 0x2e: { // swr
      const addr = R[rs] + simm;
      const al = addr & 3;
      const w = R[rt] >>> 0;
      const sh = (3 - al) * 8;
      const mask = (0xffffffff << sh) >>> 0;
      writeU32(addr & ~3, ((readU32(addr & ~3) & ~mask) | ((w << sh) & mask)) >>> 0);
      break;
    }'''
new_swr = '''    case 0x2e: { // swr - little-endian: stores lower bytes of register
      const addr = R[rs] + simm;
      const al = addr & 3;
      const w = R[rt] >>> 0;
      const sh = (3 - al) * 8;
      const mask = 0xffffffff >>> sh;
      writeU32(addr & ~3, ((readU32(addr & ~3) & (~mask >>> 0)) | (w & mask)) >>> 0);
      break;
    }'''
s = s.replace(old_swr, new_swr)

open('/app/vm.js','w').write(s)
print('patched lwl/lwr/swl/swr')
PY
